CREATE OR REPLACE PROCEDURE DB1.S2.P2()
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
DECLARE
    V1 TIMESTAMP_NTZ;
    V2 NUMBER DEFAULT 0;
BEGIN
    SELECT COALESCE(MAX(C6), '1900-01-01'::TIMESTAMP_NTZ)
    INTO V1
    FROM DB1.S2.T1;

    MERGE INTO DB1.S2.T2 tgt
    USING (SELECT C1, C3 FROM DB1.S2.T1 WHERE C6 > :V1) src
    ON tgt.C1 = src.C1
    WHEN MATCHED THEN UPDATE SET tgt.C3 = src.C3
    WHEN NOT MATCHED THEN INSERT (C1, C3) VALUES (src.C1, src.C3);

    V2 := SQLROWCOUNT;
    RETURN 'rows: ' || V2;

EXCEPTION
    WHEN OTHER THEN
        LET V3 VARCHAR := SQLERRM;
        RAISE;
END;
$$;
